-- RBI / FEMA: three combined questions split (RB01/RB07, RB05/RB08, RB06/RB09).
update public.hub_chk_points set q='Is payment for every export received within 15 months?', why='Unpaid exports beyond the time limit are a FEMA violation.', evidence='Bank statements / FIRC', updated_at=now() where code='RB01';
update public.hub_chk_points set q='Are import payments made as per contract?', why='Open entries block future import payments.', evidence='Contract + payment proof', updated_at=now() where code='RB05';
update public.hub_chk_points set q='For any foreign investment, was FC-GPR filed within 30 days?', why='Late filing needs compounding with RBI.', evidence='FC-GPR acknowledgement', updated_at=now() where code='RB06';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('RB07','RBI / FEMA','Is the bank''s EDPMS entry closed for every export?','Old open entries put the exporter on the caution list.','FEMA Export & Import Regulations 2026','exporter',array[]::text[],'H','EDPMS outstanding report',8007,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('RB08','RBI / FEMA','Are the IDPMS entries closed with the bill of entry?','Open entries block future import payments.','FEMA Export & Import Regulations 2026','importer',array[]::text[],'M','IDPMS report',8008,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('RB09','RBI / FEMA','Is the FLA return filed by 15 July?','Late filing needs compounding with RBI.','FEMA (Non-Debt Instruments) Rules 2019','fdi',array[]::text[],'H','FLA acknowledgement',8009,true,null) on conflict (code) do nothing;
